"577 :   static JSType getGreatestSubtype(JSType thisType, JSType thatType) {
578 :     if (thatType.isEmptyType() || thatType.isAllType()) {
579 :       // Defer to the implementations of the end lattice elements when
580 :       // possible.
581 :       return thatType.getGreatestSubtype(thisType);
582 :     } else if (thisType.isUnknownType() || thatType.isUnknownType()) {
583 :       // The greatest subtype with any unknown type is the universal
584 :       // unknown type, unless the two types are equal.
585 :       return thisType.equals(thatType) ? thisType :
586 :           thisType.getNativeType(JSTypeNative.UNKNOWN_TYPE);
587 :     } else if (thisType.isSubtype(thatType)) {
588 :       return thisType;
589 :     } else if (thatType.isSubtype(thisType)) {
590 :       return thatType;
591 :     } else if (thisType.isUnionType()) {
592 :       return ((UnionType) thisType).meet(thatType);
593 :     } else if (thatType.isUnionType()) {
594 :       return ((UnionType) thatType).meet(thisType);
595 :     } else if (thisType.isObject() && thatType.isObject()) {
596 :       return thisType.getNativeType(JSTypeNative.NO_OBJECT_TYPE);
597 :     }
598 :     return thisType.getNativeType(JSTypeNative.NO_TYPE);
